[
  {
    "id": "technology-skill-cites-dated-sources",
    "severity": "blocking",
    "since": "2026-09-10",
    "failureMessage": "a technology skill is trusted as verified by every session that loads it, so one that names no dated source and no verification record cannot be told from one written from memory",
    "scanFiles": "/(^|\\/)skills\\/[^/]+\\/SKILL\\.md$/",
    "scanIgnoringMarkdownFences": true,
    "checkEachFile": [
      {
        "whenFileMatches": "/^\\s+technology:\\s*\\S/m",
        "require": "/^## Sources\\s*$[\\s\\S]*?https?:\\/\\/[^\\s)]+[^\\n]*\\b\\d{4}-\\d{2}-\\d{2}\\b/m",
        "what": "declares a technology but carries no `## Sources` section with a URL and its fetch date (YYYY-MM-DD) on one line",
        "fix": "add `## Sources` with one line per document read — its URL and the date it was fetched — from the vendor's live documentation, never a search snippet"
      },
      {
        "whenFileMatches": "/^\\s+technology:\\s*\\S/m",
        "require": "/^## Verified\\s*$/m",
        "what": "declares a technology but carries no `## Verified` section",
        "fix": "add `## Verified` saying what was actually run against the vendor, when, and what came back — or that nothing was, and the date egress was blocked"
      }
    ]
  },
  {
    "id": "technology-skill-links-inside-its-folder",
    "severity": "blocking",
    "since": "2026-09-10",
    "failureMessage": "a technology skill is promoted by lifting its folder into another pack, and a link out of that folder dangles the moment it lands",
    "scanFiles": "/(^|\\/)skills\\/[^/]+\\/SKILL\\.md$/",
    "scanIgnoringMarkdownFences": true,
    "matchLines": [
      {
        "whenFileMatches": "/^\\s+technology:\\s*\\S/m",
        "match": "/\\]\\(\\.\\.\\/|\\.claudinite\\/(local|shared)\\//",
